import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ 
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    if (file.mimetype === 'application/pdf') {
      cb(null, true);
    } else {
      cb(new Error('Only PDF files are allowed'));
    }
  }
});

interface MulterRequest extends Request {
  file?: Express.Multer.File;
}

router.post('/parse-resume', upload.single('resume'), async (req: MulterRequest, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No resume file uploaded' });
      return;
    }

    const parsedPdf = await pdfParse(req.file.buffer);
    const extractedText = parsedPdf.text;

    res.status(200).json({
      success: true,
      fileName: req.file.originalname,
      pageCount: parsedPdf.numpages,
      extractedText: extractedText.trim(),
    });
  } catch (error: any) {
    res.status(500).json({ error: 'Failed to parse PDF resume', details: error.message });
  }
});

export default router;

import { useState, useMemo } from 'react';

interface KeywordMatchResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  totalKeywordsChecked: number;
}

export function useKeywordMatcher(resumeText: string, jobDescription: string) {
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false);

  const analysisResult = useMemo<KeywordMatchResult>(() => {
    if (!resumeText || !jobDescription) {
      return { matchScore: 0, matchedKeywords: [], missingKeywords: [], totalKeywordsChecked: 0 };
    }

    const cleanAndTokenize = (text: string): Set<string> => {
      const tokens = text
        .toLowerCase()
        .replace(/[^\w\s]/gi, '')
        .split(/\s+/);
      const stopWords = new Set(['and', 'the', 'to', 'a', 'of', 'in', 'for', 'is', 'on', 'with', 'as', 'an']);
      return new Set(tokens.filter(token => token.length > 2 && !stopWords.has(token)));
    };

    const resumeTokens = cleanAndTokenize(resumeText);
    const jobTokens = Array.from(cleanAndTokenize(jobDescription));

    const matched: string[] = [];
    const missing: string[] = [];

    jobTokens.forEach(token => {
      if (resumeTokens.has(token)) {
        matched.push(token);
      } else {
        missing.push(token);
      }
    });

    const total = jobTokens.length;
    const score = total > 0 ? Math.round((matched.length / total) * 100) : 0;

    return {
      matchScore: score,
      matchedKeywords: matched,
      missingKeywords: missing,
      totalKeywordsChecked: total,
    };
  }, [resumeText, jobDescription]);

  return { analysisResult, isAnalyzing, setIsAnalyzing };
}
